queries.query:
find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.build_duration > 0
| aggregate { avg(pe.build_duration / 1000.0) as avg_duration_s }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.build_duration > 0
| aggregate { percentile(pe.build_duration, 90) / 1000.0 as p90_duration_s }

find view "view:ci:stage_execution_summary" se | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate}
| filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate { avg(se.seconds_init_duration) as avg_init_s }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.moduleinfo_author_id is not null and pe.moduleinfo_author_id != ''
| aggregate { round(count() * 1.0 / nullif(distinct_count(pe.moduleinfo_author_id), 0), 1) as builds_per_dev }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.build_duration > 0
| aggregate {
    date_trunc("week", pe.startts) as week,
    round(median(pe.build_duration) / 60000.0, 2) as p50_minutes,
    round(avg(pe.build_duration) / 60000.0, 2) as avg_minutes,
    round(percentile(pe.build_duration, 90) / 60000.0, 2) as p90_minutes
  }
| group_by week
| order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.build_duration > 0
| aggregate {
    case when pe.build_duration < 60000 then "1. Under 1 min"
         when pe.build_duration < 300000 then "2. 1-5 min"
         when pe.build_duration < 900000 then "3. 5-15 min"
         else "4. Over 15 min" end as duration_bucket,
    count() as builds
  }
| group_by duration_bucket
| order_by duration_bucket asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { coalesce(pe.trigger_type, "UNKNOWN") as trigger_type, count() as builds }
| group_by trigger_type
| order_by builds desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.moduleinfo_author_id is not null and pe.moduleinfo_author_id != ''
| aggregate {
    pe.moduleinfo_author_id as developer,
    count(case when pe.status = "SUCCESS" then 1 end) as successful,
    count(case when pe.status != "SUCCESS" then 1 end) as unsuccessful
  }
| group_by developer
| order_by successful desc
| limit 10

find view "view:ci:stage_execution_summary" se | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate}
| filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate {
    case when se.infrastructure_type = "DOCKER" then "Local Runner" else se.infrastructure_type end as infrastructure,
    round(sum(se.hours_stage_duration), 2) as stage_hours
  }
| group_by infrastructure
| order_by stage_hours desc

find view "view:ci:stage_execution_summary" se | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate}
| filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate {
    se.os_type as os,
    se.resource_class as resource_class,
    round(avg(se.minutes_stage_duration), 2) as avg_stage_minutes
  }
| group_by os, resource_class
| order_by os asc

find view "view:ci:stage_execution_summary" se | filter se.start_timestamp >= cast(${start_time} as timestamp) and se.start_timestamp <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate}
| filter se.status != "SKIPPED" and se.seconds_stage_duration > 0
| aggregate {
    case when se.infrastructure_type = "DOCKER" then "Local Runner" else se.infrastructure_type end as infrastructure,
    round(avg(se.seconds_init_duration) / 60.0, 2) as setup_minutes,
    round(avg(se.seconds_stage_duration - se.seconds_init_duration) / 60.0, 2) as execution_minutes
  }
| group_by infrastructure
| order_by infrastructure asc
